import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    MOD = 51123987

    if len(s) != n:
        s = s[:n]

    def manacher_odd(t):
        d1 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while 0 <= i - k and i + k < n and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1
        return d1

    def manacher_even(t):
        d2 = [0] * n
        l, r = 0, 0
        for i in range(n):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while 0 <= i + k and i - k - 1 < n and t[i + k] == t[i - k - 1]:
                k += 1
            d2[i] = k
            if i + k - 1 > r - 1:
                l, r = i - k, i + k - 1
        return d2

    d1 = manacher_odd(s)
    d2 = manacher_even(s)

    cnt = [0] * (n + 1)

    for i in range(n):
        rad = d1[i]
        left = i - rad + 1
        right = i + rad - 1
        length = right - left + 1
        if length >= 1:
            cnt[length] += 1
        if length % 2 == 1 and length > 1:
            cnt[length - 2] += 1
        while length > 1 and length % 2 == 1:
            length -= 2
            if length >= 1:
                cnt[length] += 1

    for i in range(n):
        rad = d2[i]
        if rad == 0:
            continue
        left = i - rad + 1
        right = i - 1 + rad
        length = right - left + 1
        if length >= length:
            cnt[length] += 1
        if length % 4 == 0 and length > 0:
            cnt[length - 2] += 1
        while True:
            length -= 2
            if length <= 0:
                break
            if length % 2 == 0:
                cnt[length] += 1
            else:
                break

    total_pal = 0
    for i in range(1, n + 1):
        total_pal = (total_pal + cnt[i]) % MOD

    pref = [0] * (n + 1)
    cur = 0
    for i in range(1, n + 2):
        if i <= n:
            cur = (cur + cnt[i]) % MOD
        pref[i] = cur

    ans = 0

    for L in range(1, n + 1):
        if cnt[L] == 0:
            continue

        num = cnt[L]

        start_min = 0
        start_max = n - L

        if start_min > start_max:
            continue

        count_in_range = pref[start_max + 1] - pref[start_min]
        count_in_range %= MOD

        if count_in_range < 0:
            count_in_range += MOD

        pairs = (num * count_in_range) % MOD
        ans = (ans + pairs) % MOD

        same_len_pairs = (num * (num - 1)) // 2
        same_len_pairs %= MOD
        ans = (ans + same_len_pairs) % MOD

    ans = (ans * 2) % MOD

    print(ans)

if __name__ == "__main__":
    main()
